import { useState, useEffect, useCallback } from 'react';
import { scopedStorage } from '@lark-apaas/client-toolkit-lite';
import { format } from 'date-fns';

const STORAGE_KEY = '__app_ledlight_inquiries';
const NOTIFY_EMAIL = 'sherwin@tanjeon.com';

type InquiryMailFields = {
  name: string;
  company: string;
  email: string;
  country: string;
  product: string;
  productName?: string;
  category?: string;
  categoryName?: string;
  message: string;
  source: IInquiry['source'];
  createdAt: number;
};

export function buildMailto(inquiry: InquiryMailFields, toEmail = NOTIFY_EMAIL): string {
  const subject = `Inquiry from ${inquiry.name || inquiry.company || 'Customer'}`;
  const body = [
    'New Inquiry Received',
    '',
    `Name: ${inquiry.name || '-'}`,
    `Company: ${inquiry.company || '-'}`,
    `Email: ${inquiry.email}`,
    `Country: ${inquiry.country || '-'}`,
    `Product: ${inquiry.productName || inquiry.product || '-'}`,
    ...(inquiry.category || inquiry.categoryName
      ? [`Category: ${inquiry.categoryName || inquiry.category}`]
      : []),
    '',
    'Message:',
    inquiry.message || '-',
    '',
    `Source: ${inquiry.source}`,
    `Date: ${format(inquiry.createdAt, 'yyyy-MM-dd HH:mm:ss')}`,
  ].join('\n');
  return `mailto:${encodeURIComponent(toEmail)}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
}

export type EmailStatus = 'unsent' | 'sending' | 'sent' | 'failed';

export interface IInquiry {
  id: string;
  name: string;
  company: string;
  email: string;
  country: string;
  product: string; // product id or 'all'
  productName?: string;
  category?: string;
  categoryName?: string;
  message: string;
  source: 'home' | 'contact' | 'product';
  status: 'unread' | 'read' | 'replied';
  emailStatus: EmailStatus;
  emailError?: string;
  createdAt: number;
}

function loadInquiries(): IInquiry[] {
  try {
    const raw = scopedStorage.getItem(STORAGE_KEY);
    if (raw) {
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) {
        // 兼容旧数据：没有 emailStatus 字段的补齐
        return parsed.map((item) => ({
          emailStatus: 'unsent' as const,
          ...item,
        }));
      }
    }
  } catch {
    // ignore
  }
  return [];
}

function saveInquiries(list: IInquiry[]) {
  try {
    scopedStorage.setItem(STORAGE_KEY, JSON.stringify(list));
  } catch {
    // ignore
  }
}

export function useInquiries() {
  const [inquiries, setInquiries] = useState<IInquiry[]>([]);
  const [loaded, setLoaded] = useState(false);

  useEffect(() => {
    setInquiries(loadInquiries());
    setLoaded(true);
  }, []);

  const addInquiry = useCallback((data: Omit<IInquiry, 'id' | 'status' | 'createdAt' | 'emailStatus'> & { emailStatus?: EmailStatus }) => {
    const newItem: IInquiry = {
      ...data,
      id: `inq_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
      status: 'unread',
      emailStatus: data.emailStatus || 'unsent',
      createdAt: Date.now(),
    };
    setInquiries((prev) => {
      const next = [newItem, ...prev];
      saveInquiries(next);
      return next;
    });
    return newItem;
  }, []);

  const updateEmailStatus = useCallback((id: string, emailStatus: EmailStatus, emailError?: string) => {
    setInquiries((prev) => {
      const next = prev.map((i) => (i.id === id ? { ...i, emailStatus, emailError } : i));
      saveInquiries(next);
      return next;
    });
  }, []);

  /**
   * Send inquiry email via Formspree endpoint.
   * Returns true on success, false on failure.
   * Does NOT throw - errors are logged and reflected in emailStatus.
   */
  const sendInquiryEmail = useCallback(async (inquiry: IInquiry, endpoint: string, recipientEmail: string): Promise<boolean> => {
    if (!endpoint) return false;
    updateEmailStatus(inquiry.id, 'sending');
    try {
      const res = await fetch(endpoint, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Accept': 'application/json',
        },
        body: JSON.stringify({
          name: inquiry.name || '-',
          company: inquiry.company || '-',
          email: inquiry.email,
          country: inquiry.country || '-',
          product: inquiry.productName || inquiry.product || '-',
          message: inquiry.message || '-',
          source: inquiry.source,
          date: format(inquiry.createdAt, 'yyyy-MM-dd HH:mm:ss'),
          _subject: `Inquiry from ${inquiry.name || inquiry.company || 'Customer'}`,
          _to: recipientEmail || NOTIFY_EMAIL,
        }),
      });
      if (res.ok) {
        updateEmailStatus(inquiry.id, 'sent');
        return true;
      }
      const errText = await res.text().catch(() => 'HTTP error');
      updateEmailStatus(inquiry.id, 'failed', `${res.status} ${errText.slice(0, 80)}`);
      return false;
    } catch (err) {
      updateEmailStatus(inquiry.id, 'failed', err instanceof Error ? err.message : 'Network error');
      return false;
    }
  }, [updateEmailStatus]);

  const updateStatus = useCallback((id: string, status: IInquiry['status']) => {
    setInquiries((prev) => {
      const next = prev.map((i) => (i.id === id ? { ...i, status } : i));
      saveInquiries(next);
      return next;
    });
  }, []);

  const deleteInquiry = useCallback((id: string) => {
    setInquiries((prev) => {
      const next = prev.filter((i) => i.id !== id);
      saveInquiries(next);
      return next;
    });
  }, []);

  const clearAll = useCallback(() => {
    setInquiries([]);
    saveInquiries([]);
  }, []);

  const unreadCount = inquiries.filter((i) => i.status === 'unread').length;

  return {
    inquiries,
    loaded,
    addInquiry,
    updateStatus,
    deleteInquiry,
    clearAll,
    unreadCount,
    totalCount: inquiries.length,
    buildMailto,
    notifyEmail: NOTIFY_EMAIL,
    sendInquiryEmail,
    updateEmailStatus,
  };
}
